  // History for Undo/Redo (Simplified)
  const [history, setHistory] = useState<EditorElement[][]>([[INITIAL_ELEMENT]]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const addToHistory = (newElements: EditorElement[]) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newElements);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const updateElements = (newElements: EditorElement[]) => {
    setElements(newElements);
    addToHistory(newElements);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      setHistoryIndex(historyIndex - 1);
      setElements(history[historyIndex - 1]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      setHistoryIndex(historyIndex + 1);
      setElements(history[historyIndex + 1]);
    }
  };

  const handleAddElement = (type: ElementType) => {
    const id = Date.now().toString();
    const newElement: EditorElement = {
      id,
      type,
      x: 100, // Default spawn position
      y: 100,
      width: type === 'text' ? 200 : 100,
      height: type === 'text' ? 60 : 100,
      content: type === 'text' ? 'テキスト' : type === 'button' ? 'ボタン' : '',
      style: {
        backgroundColor: type === 'rectangle' ? '#e2e8f0' : type === 'button' ? '#3b82f6' : 'transparent',
        borderRadius: type === 'circle' ? 100 : type === 'button' ? 8 : 0,
        color: type === 'button' ? '#ffffff' : '#000000',
        fontSize: 16,
        textAlign: 'center',
      },
      src: type === 'image' ? `https://picsum.photos/300/300?random=${id}` : undefined,
    };

    const newElements = [...elements, newElement];
    setElements(newElements);
    addToHistory(newElements);
    setSelectedId(id);
  };

  const handleUpdateElement = useCallback((id: string, updates: Partial<EditorElement>) => {
    setElements(prev => {
        // We only want to add to history on mouse up (drag end), but simpler here to just update state
        // For a real app, you'd debounce the history push or separate "commit" from "update"
        const next = prev.map(el => el.id === id ? { ...el, ...updates, style: { ...el.style, ...updates.style } } : el);
        return next;
    });
  }, []);

  // A wrapper to commit change to history (passed to mouse up events usually, but for now simplified)
  // In a robust app, we'd trigger history save on "DragEnd" or "Blur"
  // Here, we just rely on the user manually interacting. 
  // Note: Dragging updates state frequently. History might get flooded. 
  // Fixing history flood is out of scope for this size, but generally you debounce history pushes.

  const handleDeleteElement = (id: string) => {
    const newElements = elements.filter(el => el.id !== id);
    updateElements(newElements);
    setSelectedId(null);
  };

  const handleDuplicateElement = (element: EditorElement) => {
    const newElement = {
        ...element,
        id: Date.now().toString(),
        x: element.x + 20,
        y: element.y + 20,
    };
    const newElements = [...elements, newElement];
    updateElements(newElements);
    setSelectedId(newElement.id);
  };

  const handleExport = () => {
    const code = generateCode(elements);
    downloadHtml(code);
  };

  const selectedElement = elements.find(el => el.id === selectedId) || null;

  return (
    <div className="flex h-screen flex-col overflow-hidden text-slate-800">
      {/* Top Navigation */}
      <header className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0 z-20">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">
            FB
          </div>
          <h1 className="font-bold text-lg tracking-tight">FriendBuilder</h1>
        </div>

        <div className="flex items-center gap-4">
            <div className="flex bg-gray-100 rounded-md p-1 gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Undo size={16}/></button>
                <button onClick={handleRedo} disabled={historyIndex === history.length -1} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Redo size={16}/></button>
            </div>
            <div className="h-6 w-px bg-gray-300 mx-2"></div>
            <button 
                onClick={handleExport}
                className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-700 transition shadow-sm"
            >
                <Download size={16} />
                <span>書き出し (HTML)</span>
            </button>
        </div>
      </header>

      {/* Main Workspace */}
      <div className="flex flex-1 overflow-hidden relative">
        <Toolbar onAdd={handleAddElement} />

        {/* Canvas Area */}
        <div 
            className="flex-1 bg-gray-100 overflow-auto relative flex justify-center p-12"
            onClick={() => setSelectedId(null)}
        >
            {/* Zoom Controls */}
            <div className="absolute bottom-6 left-6 flex bg-white shadow-lg rounded-full p-1 gap-2 z-20">
                <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 hover:bg-gray-100 rounded-full"><ZoomOut size={16}/></button>
                <span className="text-xs flex items-center font-medium w-8 justify-center">{Math.round(zoom * 100)}%</span>
                <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-2 hover:bg-gray-100 rounded-full"><ZoomIn size={16}/></button>
            </div>

            <div 
                className="bg-white shadow-xl transition-all relative overflow-hidden"
                style={{ 
                    width: '800px', 
                    height: '600px',
                    transform: `scale(${zoom})`,
                    transformOrigin: 'top center',
                    backgroundImage: 'radial-gradient(#e5e7eb 1px, transparent 1px)',
                    backgroundSize: '20px 20px'
                }}
                onClick={(e) => e.stopPropagation()} // Prevent deselection when clicking canvas bg
            >
                {elements.map(el => (
                    <CanvasElement 
                        key={el.id}
                        element={el}
                        isSelected={el.id === selectedId}
                        onSelect={setSelectedId}
                        onUpdate={handleUpdateElement}
                        zoom={zoom}
                    />
                ))}
            </div>
        </div>

        <PropertiesPanel 
            element={selectedElement} 
            onUpdate={handleUpdateElement}
            onDelete={handleDeleteElement}
            onDuplicate={handleDuplicateElement}
        />
      </div>
    </div>
  );
};

export default App;

export type ElementType = 'text' | 'rectangle' | 'circle' | 'image' | 'button';

export type AnchorX = 'left' | 'center' | 'right';
export type AnchorY = 'top' | 'center' | 'bottom';

export interface EditorElement {
  id: string;
  type: ElementType;
  // x and y now represent the OFFSET from the anchor point
  x: number; 
  y: number;
  anchorX: AnchorX;
  anchorY: AnchorY;
  width: number;
  height: number;
  content?: string;
  style: {
    backgroundColor?: string;
    color?: string;
    fontSize?: number;
    fontWeight?: string;
    borderRadius?: number;
    borderWidth?: number;
    borderColor?: string;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    zIndex?: number;
    boxShadow?: string;
  };
  src?: string; // For images
  link?: string; // For link interaction
}

export const PRESET_COLORS = [
  '#ffffff', '#000000', '#ef4444', '#f97316', '#f59e0b', 
  '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#6366f1', 
  '#8b5cf6', '#d946ef', '#f43f5e', '#64748b'
];

import { EditorElement } from '../types';

export const generateCode = (elements: EditorElement[]) => {
  const css = `
    * { box-sizing: border-box; }
    body { margin: 0; padding: 0; background-color: #ffffff; font-family: sans-serif; overflow-x: hidden; }
    .container { position: relative; width: 100%; max-width: 1280px; min-height: 800px; margin: 0 auto; overflow: hidden; background-color: white; box-shadow: 0 0 20px rgba(0,0,0,0.05); }
    .element { position: absolute; display: flex; align-items: center; overflow: hidden; }
    .text-element { align-items: flex-start; }
    .btn-element { justify-content: center; cursor: pointer; transition: transform 0.1s; }
    .btn-element:active { transform: scale(0.98); }
  `;

  const generateStyleString = (el: EditorElement) => {
    const styles: string[] = [
      `width: ${el.width}px`,
      `height: ${el.height}px`,
      `z-index: ${el.style.zIndex || 1}`,
      `opacity: ${el.style.opacity || 1}`,
    ];

    // Handle Horizontal Anchoring
    if (el.anchorX === 'left') {
      styles.push(`left: ${el.x}px`);
    } else if (el.anchorX === 'right') {
      styles.push(`right: ${el.x}px`);
    } else if (el.anchorX === 'center') {
      styles.push(`left: 50%`);
      // Translate X based on center anchor + offset
      // If we use margin-left for offset, it's cleaner than double translate
      styles.push(`margin-left: ${el.x}px`); 
      styles.push(`transform: translateX(-50%)`);
    }

    // Handle Vertical Anchoring
    // Note: If X is center, we already have a transform. We need to merge them if Y is also center.
    let transformString = el.anchorX === 'center' ? 'translateX(-50%)' : '';

    if (el.anchorY === 'top') {
      styles.push(`top: ${el.y}px`);
    } else if (el.anchorY === 'bottom') {
      styles.push(`bottom: ${el.y}px`);
    } else if (el.anchorY === 'center') {
      styles.push(`top: 50%`);
      styles.push(`margin-top: ${el.y}px`);
      if (transformString) {
        transformString += ' translateY(-50%)';
      } else {
        transformString = 'translateY(-50%)';
      }
    }

    if (transformString) {
        // Remove the previous transform push if it existed (simple check)
        const idx = styles.findIndex(s => s.startsWith('transform:'));
        if (idx !== -1) styles.splice(idx, 1);
        styles.push(`transform: ${transformString}`);
    }

    if (el.style.backgroundColor) styles.push(`background-color: ${el.style.backgroundColor}`);
    if (el.style.color) styles.push(`color: ${el.style.color}`);
    if (el.style.fontSize) styles.push(`font-size: ${el.style.fontSize}px`);
    if (el.style.fontWeight) styles.push(`font-weight: ${el.style.fontWeight}`);
    if (el.style.borderRadius) styles.push(`border-radius: ${el.style.borderRadius}px`);
    if (el.style.borderWidth) styles.push(`border: ${el.style.borderWidth}px solid ${el.style.borderColor || 'black'}`);
    if (el.style.textAlign) styles.push(`text-align: ${el.style.textAlign}`);
    if (el.style.boxShadow) styles.push(`box-shadow: ${el.style.boxShadow}`);

    // Flex alignment for text vs others
    if (el.type !== 'text') {
        styles.push(`justify-content: center`);
    } else {
        if (el.style.textAlign === 'center') styles.push('justify-content: center');
        if (el.style.textAlign === 'right') styles.push('justify-content: flex-end');
    }

    return styles.join('; ');
  };

  const htmlElements = elements.map(el => {
    const styleString = generateStyleString(el);
    let contentHtml = '';

    if (el.type === 'image' && el.src) {
      contentHtml = `<img src="${el.src}" style="width: 100%; height: 100%; object-fit: cover; border-radius: inherit;" alt="Image" />`;
    } else if (el.type === 'text') {
       contentHtml = `<div style="width: 100%; word-wrap: break-word;">${el.content || ''}</div>`;
    } else {
      contentHtml = `<span>${el.content || ''}</span>`;
    }

    const className = el.type === 'button' ? 'element btn-element' : el.type === 'text' ? 'element text-element' : 'element';

    if (el.link) {
        return `<a href="${el.link}" class="${className}" style="${styleString}; text-decoration: none;">${contentHtml}</a>`;
    }

    return `<div id="${el.id}" class="${className}" style="${styleString}">
      ${contentHtml}
    </div>`;
  }).join('\n    ');

  const fullHtml = `<!DOCTYPE html>
<html lang="ja">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>My Friendly Site</title>
    <style>${css}</style>
</head>
<body>
    <div class="container">
    ${htmlElements}
    </div>
</body>
</html>`;

  return fullHtml;
};

export const downloadHtml = (content: string) => {
  const blob = new Blob([content], { type: 'text/html' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'friendly-site.html';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

import React, { useRef, useState } from 'react';
import { EditorElement } from '../types';

interface CanvasElementProps {
  element: EditorElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onUpdate: (id: string, updates: Partial<EditorElement>) => void;
  zoom: number;
}

const CanvasElement: React.FC<CanvasElementProps> = ({ element, isSelected, onSelect, onUpdate, zoom }) => {
  const elementRef = useRef<HTMLDivElement>(null);

  // Drag State
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialOffset, setInitialOffset] = useState({ x: 0, y: 0 });

  // Resize State
  const [isResizing, setIsResizing] = useState(false);
  const [resizeHandle, setResizeHandle] = useState<string | null>(null);
  const [initialSize, setInitialSize] = useState({ w: 0, h: 0, x: 0, y: 0 });

  // --- Dragging Logic ---
  const handlePointerDown = (e: React.PointerEvent) => {
    e.stopPropagation();
    if (e.button !== 0) return;

    onSelect(element.id);
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialOffset({ x: element.x, y: element.y });

    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const dx = (e.clientX - dragStart.x) / zoom;
      const dy = (e.clientY - dragStart.y) / zoom;

      let newX = initialOffset.x;
      let newY = initialOffset.y;

      // Logic: If anchored Left, moving right increases X.
      // If anchored Right, moving right DECREASES X (distance from right edge).
      if (element.anchorX === 'left') newX += dx;
      else if (element.anchorX === 'right') newX -= dx;
      else if (element.anchorX === 'center') newX += dx; // X is offset from center

      if (element.anchorY === 'top') newY += dy;
      else if (element.anchorY === 'bottom') newY -= dy;
      else if (element.anchorY === 'center') newY += dy;

      onUpdate(element.id, {
        x: Math.round(newX),
        y: Math.round(newY)
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      setIsDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    }
  };

  // --- Resizing Logic ---
  const handleResizeStart = (e: React.PointerEvent, handle: string) => {
    e.stopPropagation();
    e.preventDefault();
    setIsResizing(true);
    setResizeHandle(handle);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialSize({ w: element.width, h: element.height, x: element.x, y: element.y });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handleResizeMove = (e: React.PointerEvent) => {
    if (!isResizing) return;
    e.stopPropagation();

    const dx = (e.clientX - dragStart.x) / zoom;
    const dy = (e.clientY - dragStart.y) / zoom;

    let newWidth = initialSize.w;
    let newHeight = initialSize.h;
    let newX = initialSize.x;
    let newY = initialSize.y;

    // Simplified resize logic for anchors.
    // Ideally, resizing Left handle when anchored Right should just increase Width, not move X.
    // However, to keep it intuitive like a graphics editor, we often want the "Other side" to stay fixed visually.

    // For this implementation, we will apply simple size changes. 
    // If the user resizes from the anchor side (e.g. resizes Left handle while Anchored Left), 
    // it usually means shifting the start point.

    const isAnchorRight = element.anchorX === 'right';
    const isAnchorBottom = element.anchorY === 'bottom';
    // Center anchors make resizing asymmetric logic complicated, so we default to standard top-left expansion feel for simplicity or just width change.

    if (resizeHandle?.includes('e')) {
        newWidth = Math.max(20, initialSize.w + dx);
    }
    if (resizeHandle?.includes('s')) {
        newHeight = Math.max(20, initialSize.h + dy);
    }
    if (resizeHandle?.includes('w')) {
        const change = -dx;
        newWidth = Math.max(20, initialSize.w + change);
        // If anchored left, we must move X to compensate for width growth to keeping right side stable? 
        // No, standard behavior: dragging left handle moves left edge.
        if (element.anchorX === 'left') {
             newX = initialSize.x - change;
        } else if (element.anchorX === 'right') {
             // If anchored right, increasing width to the left doesn't change "Right" value.
             // It just makes it wider.
        } else {
             // Center: complicated, let's just change width for now to avoid jumpiness
             newX = initialSize.x - (change / 2);
        }
    }
    if (resizeHandle?.includes('n')) {
        const change = -dy;
        newHeight = Math.max(20, initialSize.h + change);
        if (element.anchorY === 'top') {
             newY = initialSize.y - change;
        } else if (element.anchorY === 'center') {
             newY = initialSize.y - (change / 2);
        }
    }

    onUpdate(element.id, {
        width: Math.round(newWidth),
        height: Math.round(newHeight),
        x: Math.round(newX),
        y: Math.round(newY)
    });
  };

  const handleResizeUp = (e: React.PointerEvent) => {
    if (isResizing) {
        setIsResizing(false);
        setResizeHandle(null);
        (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    }
  };

  // --- Style Construction ---
  // Construct the CSS directly from anchor data to preview exactly what the output HTML will do
  const style: React.CSSProperties = {
    position: 'absolute',
    width: `${element.width}px`,
    height: `${element.height}px`,

    // X Position
    left: element.anchorX === 'left' ? `${element.x}px` : element.anchorX === 'center' ? '50%' : undefined,
    right: element.anchorX === 'right' ? `${element.x}px` : undefined,

    // Y Position
    top: element.anchorY === 'top' ? `${element.y}px` : element.anchorY === 'center' ? '50%' : undefined,
    bottom: element.anchorY === 'bottom' ? `${element.y}px` : undefined,

    // Transformations for Centering
    transform: `
      ${element.anchorX === 'center' ? 'translateX(-50%)' : ''} 
      ${element.anchorY === 'center' ? 'translateY(-50%)' : ''}
    `.trim(),

    // Center Offsets (if center anchored, x/y act as margin offsets)
    marginLeft: element.anchorX === 'center' ? `${element.x}px` : undefined,
    marginTop: element.anchorY === 'center' ? `${element.y}px` : undefined,

    backgroundColor: element.style.backgroundColor,
    color: element.style.color,
    fontSize: `${element.style.fontSize}px`,
    fontWeight: element.style.fontWeight,
    borderRadius: `${element.style.borderRadius}px`,
    borderWidth: `${element.style.borderWidth}px`,
    borderColor: element.style.borderColor,
    borderStyle: element.style.borderWidth ? 'solid' : 'none',
    textAlign: element.style.textAlign,
    opacity: element.style.opacity,
    zIndex: element.style.zIndex,
    boxShadow: element.style.boxShadow,
    display: 'flex',
    alignItems: element.type === 'text' ? 'flex-start' : 'center',
    justifyContent: element.type === 'text' 
      ? (element.style.textAlign === 'center' ? 'center' : element.style.textAlign === 'right' ? 'flex-end' : 'flex-start') 
      : 'center',
    cursor: isDragging ? 'grabbing' : 'grab',
    userSelect: 'none',
  };

  // Helper to render resize handle at correct visual position based on width/height
  // Note: Handles are absolutely positioned relative to the element, so left/top=0 is TopLeft of element.
  const handleStyle = (pos: string) => {
      const s: React.CSSProperties = { position: 'absolute', width: 10, height: 10, background: 'white', border: '1px solid #6366f1', borderRadius: '50%', zIndex: 50 };
      if (pos === 'nw') { s.left = -5; s.top = -5; s.cursor = 'nw-resize'; }
      if (pos === 'ne') { s.right = -5; s.top = -5; s.cursor = 'ne-resize'; }
      if (pos === 'sw') { s.left = -5; s.bottom = -5; s.cursor = 'sw-resize'; }
      if (pos === 'se') { s.right = -5; s.bottom = -5; s.cursor = 'se-resize'; }
      return s;
  };

  return (
    <>
      <div
        ref={elementRef}
        style={style}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        className={`group ${isSelected ? 'ring-2 ring-indigo-500' : 'hover:ring-1 hover:ring-indigo-300'}`}
        onDoubleClick={(e) => {
             e.stopPropagation();
             if(element.type === 'text') {
                 const newContent = prompt("テキストを編集", element.content);
                 if(newContent !== null) onUpdate(element.id, { content: newContent });
             }
        }}
      >
        {element.type === 'image' ? (
          <img src={element.src} alt="" className="w-full h-full object-cover pointer-events-none" style={{ borderRadius: 'inherit' }} />
        ) : (
          <div className="w-full h-full p-2 break-words whitespace-pre-wrap pointer-events-none">
            {element.content}
          </div>
        )}

        {/* Render resize handles inside the element div but offset, so they move with it */}
        {isSelected && (
            <>
                <div style={handleStyle('nw')} onPointerDown={(e) => handleResizeStart(e, 'nw')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('ne')} onPointerDown={(e) => handleResizeStart(e, 'ne')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('sw')} onPointerDown={(e) => handleResizeStart(e, 'sw')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('se')} onPointerDown={(e) => handleResizeStart(e, 'se')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
            </>
        )}
      </div>
    </>
  );
};

export default CanvasElement;

import React from 'react';
import { EditorElement, AnchorX, AnchorY, PRESET_COLORS } from '../types';
import { Trash2, AlignLeft, AlignCenter, AlignRight, Copy, ArrowRight, ArrowDown } from 'lucide-react';

interface PropertiesPanelProps {
  element: EditorElement | null;
  onUpdate: (id: string, updates: Partial<EditorElement>) => void;
  onDelete: (id: string) => void;
  onDuplicate: (element: EditorElement) => void;
  canvasWidth: number;
  canvasHeight: number;
}

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ element, onUpdate, onDelete, onDuplicate, canvasWidth, canvasHeight }) => {
  if (!element) {
    return (
      <div className="w-80 bg-white border-l border-gray-200 p-6 flex flex-col items-center justify-center text-gray-400 z-10 shrink-0">
        <p className="text-sm text-center">要素を選択して<br/>編集してください</p>
      </div>
    );
  }

  const updateStyle = (key: keyof typeof element.style, value: any) => {
    onUpdate(element.id, {
      style: { ...element.style, [key]: value }
    });
  };

  // Smart Anchor Switching: Calculates new X/Y so the element stays visually stationary
  const changeAnchor = (newXAnchor: AnchorX, newYAnchor: AnchorY) => {
    let currentAbsLeft = 0;
    let currentAbsTop = 0;

    // 1. Calculate current absolute Left/Top (pixels from top-left)
    if (element.anchorX === 'left') currentAbsLeft = element.x;
    else if (element.anchorX === 'right') currentAbsLeft = canvasWidth - element.width - element.x;
    else if (element.anchorX === 'center') currentAbsLeft = (canvasWidth / 2) + element.x - (element.width / 2);

    if (element.anchorY === 'top') currentAbsTop = element.y;
    else if (element.anchorY === 'bottom') currentAbsTop = canvasHeight - element.height - element.y;
    else if (element.anchorY === 'center') currentAbsTop = (canvasHeight / 2) + element.y - (element.height / 2);

    // 2. Calculate new Offset based on new Anchors
    let newX = 0;
    let newY = 0;

    if (newXAnchor === 'left') newX = currentAbsLeft;
    else if (newXAnchor === 'right') newX = canvasWidth - element.width - currentAbsLeft;
    else if (newXAnchor === 'center') newX = currentAbsLeft - (canvasWidth / 2) + (element.width / 2);

    if (newYAnchor === 'top') newY = currentAbsTop;
    else if (newYAnchor === 'bottom') newY = canvasHeight - element.height - currentAbsTop;
    else if (newYAnchor === 'center') newY = currentAbsTop - (canvasHeight / 2) + (element.height / 2);

    onUpdate(element.id, {
        anchorX: newXAnchor,
        anchorY: newYAnchor,
        x: Math.round(newX),
        y: Math.round(newY)
    });
  };

  const AnchorGrid = () => (
      <div className="grid grid-cols-3 gap-1 w-20 h-20 bg-gray-100 p-1 rounded">
          {['top', 'center', 'bottom'].map(y => (
              ['left', 'center', 'right'].map(x => {
                  const isActive = element.anchorX === x && element.anchorY === y;
                  return (
                      <button 
                        key={`${x}-${y}`}
                        onClick={() => changeAnchor(x as AnchorX, y as AnchorY)}
                        className={`rounded-sm border ${isActive ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-gray-300 hover:border-gray-400'}`}
                        title={`${y} - ${x}`}
                      />
                  )
              })
          ))}
      </div>
  );

  return (
    <div className="w-80 bg-white border-l border-gray-200 flex flex-col z-10 shrink-0 h-full overflow-y-auto">
      <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
        <span className="font-semibold text-gray-700 text-sm">プロパティ</span>
        <div className="flex gap-2">
           <button 
            onClick={() => onDuplicate(element)}
            className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded transition"
            title="複製"
          >
            <Copy size={16} />
          </button>
          <button 
            onClick={() => onDelete(element.id)}
            className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded transition"
            title="削除"
          >
            <Trash2 size={16} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-6">

        {/* Content Section */}
        {element.type === 'text' || element.type === 'button' ? (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">テキスト内容</label>
            <textarea
              className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
              rows={3}
              value={element.content}
              onChange={(e) => onUpdate(element.id, { content: e.target.value })}
            />
          </div>
        ) : null}

        {element.type === 'image' && (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">画像 URL</label>
            <input
              type="text"
              className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={element.src || ''}
              onChange={(e) => onUpdate(element.id, { src: e.target.value })}
            />
          </div>
        )}

        {/* CSS Positioning & Anchor */}
        <div className="space-y-3">
          <label className="text-xs font-semibold text-gray-500 uppercase flex items-center justify-between">
              <span>配置・サイズ (CSS)</span>
          </label>

          <div className="flex gap-4">
              <div className="flex flex-col gap-1 items-center">
                   <span className="text-[10px] text-gray-400">基準位置</span>
                   <AnchorGrid />
              </div>
              <div className="flex-1 space-y-2">
                 <div className="grid grid-cols-2 gap-2">
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                            {element.anchorX === 'left' ? <ArrowRight size={10}/> : element.anchorX === 'right' ? <ArrowRight size={10} className="rotate-180"/> : <ArrowRight size={10} className="text-transparent"/>}
                            {element.anchorX === 'left' ? '左から' : element.anchorX === 'right' ? '右から' : '中央オフセット'}
                        </label>
                        <input type="number" value={element.x} onChange={(e) => onUpdate(element.id, { x: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                             {element.anchorY === 'top' ? <ArrowDown size={10}/> : element.anchorY === 'bottom' ? <ArrowDown size={10} className="rotate-180"/> : <ArrowDown size={10} className="text-transparent"/>}
                            {element.anchorY === 'top' ? '上から' : element.anchorY === 'bottom' ? '下から' : '中央オフセット'}
                        </label>
                        <input type="number" value={element.y} onChange={(e) => onUpdate(element.id, { y: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">幅 (px)</label>
                        <input type="number" value={element.width} onChange={(e) => onUpdate(element.id, { width: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">高さ (px)</label>
                        <input type="number" value={element.height} onChange={(e) => onUpdate(element.id, { height: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                 </div>
              </div>
          </div>
        </div>

        {/* Typography */}
        {(element.type === 'text' || element.type === 'button') && (
           <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">タイポグラフィ</label>
            <div className="flex gap-2">
                 <input 
                    type="number" 
                    value={element.style.fontSize || 16} 
                    onChange={(e) => updateStyle('fontSize', Number(e.target.value))}
                    className="w-20 p-2 border rounded text-sm"
                    title="フォントサイズ"
                 />
                 <div className="flex border rounded overflow-hidden">
                    <button onClick={() => updateStyle('textAlign', 'left')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'left' ? 'bg-gray-100' : ''}`}><AlignLeft size={16}/></button>
                    <button onClick={() => updateStyle('textAlign', 'center')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'center' ? 'bg-gray-100' : ''}`}><AlignCenter size={16}/></button>
                    <button onClick={() => updateStyle('textAlign', 'right')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'right' ? 'bg-gray-100' : ''}`}><AlignRight size={16}/></button>
                 </div>
            </div>
            <div className="flex gap-2 items-center">
                <input 
                    type="color" 
