import React, { useState, useCallback } from 'react';
import Toolbar from './components/Toolbar';
import PropertiesPanel from './components/PropertiesPanel';
import CanvasElement from './components/CanvasElement';
import { EditorElement, ElementType } from './types';
import { generateCode, downloadHtml } from './utils/codeGenerator';
import { Download, Undo, Redo, ZoomIn, ZoomOut } from 'lucide-react';

const CANVAS_WIDTH = 1280;
const CANVAS_HEIGHT = 800;

// Sample placeholder data
const INITIAL_ELEMENT: EditorElement = {
  id: '1',
  type: 'text',
  x: 0,
  y: 0,
  anchorX: 'center',
  anchorY: 'center',
  width: 400,
  height: 120,
  content: 'FriendBuilderへようこそ！\nここをダブルクリックして編集できます。',
  style: {
    color: '#333333',
    fontSize: 24,
    fontWeight: 'bold',
    textAlign: 'center',
    backgroundColor: 'transparent',
  }
};

const App: React.FC = () => {
  const [elements, setElements] = useState<EditorElement[]>([INITIAL_ELEMENT]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState(0.7); // Start zoomed out to see full width

  const [history, setHistory] = useState<EditorElement[][]>([[INITIAL_ELEMENT]]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const addToHistory = (newElements: EditorElement[]) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newElements);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  };

  const updateElements = (newElements: EditorElement[]) => {
    setElements(newElements);
    addToHistory(newElements);
  };

  const handleUndo = () => {
    if (historyIndex > 0) {
      setHistoryIndex(historyIndex - 1);
      setElements(history[historyIndex - 1]);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      setHistoryIndex(historyIndex + 1);
      setElements(history[historyIndex + 1]);
    }
  };

  const handleAddElement = (type: ElementType) => {
    const id = Date.now().toString();
    const newElement: EditorElement = {
      id,
      type,
      // Default to Top-Left anchoring for new elements
      x: 100, 
      y: 100,
      anchorX: 'left',
      anchorY: 'top',
      width: type === 'text' ? 200 : 100,
      height: type === 'text' ? 60 : 100,
      content: type === 'text' ? 'テキスト' : type === 'button' ? 'ボタン' : '',
      style: {
        backgroundColor: type === 'rectangle' ? '#e2e8f0' : type === 'button' ? '#3b82f6' : 'transparent',
        borderRadius: type === 'circle' ? 100 : type === 'button' ? 8 : 0,
        color: type === 'button' ? '#ffffff' : '#000000',
        fontSize: 16,
        textAlign: 'center',
      },
      src: type === 'image' ? `https://picsum.photos/300/300?random=${id}` : undefined,
    };

    const newElements = [...elements, newElement];
    setElements(newElements);
    addToHistory(newElements);
    setSelectedId(id);
  };

  const handleUpdateElement = useCallback((id: string, updates: Partial<EditorElement>) => {
    setElements(prev => {
        const next = prev.map(el => el.id === id ? { ...el, ...updates, style: { ...el.style, ...updates.style } } : el);
        return next;
    });
  }, []);

  const handleDeleteElement = (id: string) => {
    const newElements = elements.filter(el => el.id !== id);
    updateElements(newElements);
    setSelectedId(null);
  };

  const handleDuplicateElement = (element: EditorElement) => {
    const newElement = {
        ...element,
        id: Date.now().toString(),
        x: element.x + 20,
        y: element.y + 20,
    };
    const newElements = [...elements, newElement];
    updateElements(newElements);
    setSelectedId(newElement.id);
  };

  const handleExport = () => {
    const code = generateCode(elements);
    downloadHtml(code);
  };

  const selectedElement = elements.find(el => el.id === selectedId) || null;

  return (
    <div className="flex h-screen flex-col overflow-hidden text-slate-800">
      <header className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0 z-20">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">
            FB
          </div>
          <h1 className="font-bold text-lg tracking-tight">FriendBuilder</h1>
        </div>

        <div className="flex items-center gap-4">
            <div className="flex bg-gray-100 rounded-md p-1 gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Undo size={16}/></button>
                <button onClick={handleRedo} disabled={historyIndex === history.length -1} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Redo size={16}/></button>
            </div>
            <div className="h-6 w-px bg-gray-300 mx-2"></div>
            <button 
                onClick={handleExport}
                className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-700 transition shadow-sm"
            >
                <Download size={16} />
                <span>書き出し (HTML)</span>
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <Toolbar onAdd={handleAddElement} />

        {/* Canvas Area */}
        <div 
            className="flex-1 bg-gray-100 overflow-auto relative flex justify-center p-12"
            onClick={() => setSelectedId(null)}
        >
            <div className="absolute bottom-6 left-6 flex bg-white shadow-lg rounded-full p-1 gap-2 z-20">
                <button onClick={() => setZoom(z => Math.max(0.2, z - 0.1))} className="p-2 hover:bg-gray-100 rounded-full"><ZoomOut size={16}/></button>
                <span className="text-xs flex items-center font-medium w-8 justify-center">{Math.round(zoom * 100)}%</span>
                <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-2 hover:bg-gray-100 rounded-full"><ZoomIn size={16}/></button>
            </div>

            <div 
                className="bg-white shadow-xl transition-all relative overflow-hidden shrink-0"
                style={{ 
                    width: `${CANVAS_WIDTH}px`, 
                    height: `${CANVAS_HEIGHT}px`,
                    transform: `scale(${zoom})`,
                    transformOrigin: 'top center',
                    backgroundImage: 'radial-gradient(#e5e7eb 1px, transparent 1px)',
                    backgroundSize: '20px 20px'
                }}
                onClick={(e) => e.stopPropagation()} 
            >
                {elements.map(el => (
                    <CanvasElement 
                        key={el.id}
                        element={el}
                        isSelected={el.id === selectedId}
                        onSelect={setSelectedId}
                        onUpdate={handleUpdateElement}
                        zoom={zoom}
                    />
                ))}
            </div>
        </div>

        <PropertiesPanel 
            element={selectedElement} 
            onUpdate={handleUpdateElement}
            onDelete={handleDeleteElement}
            onDuplicate={handleDuplicateElement}
            canvasWidth={CANVAS_WIDTH}
            canvasHeight={CANVAS_HEIGHT}
        />
      </div>
    </div>
  );
};

export default App;

