import React, { useRef, useState } from 'react';
import { EditorElement } from '../types';

interface CanvasElementProps {
  element: EditorElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onUpdate: (id: string, updates: Partial<EditorElement>) => void;
  zoom: number;
}

const CanvasElement: React.FC<CanvasElementProps> = ({ element, isSelected, onSelect, onUpdate, zoom }) => {
  const elementRef = useRef<HTMLDivElement>(null);

  // Drag State
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialOffset, setInitialOffset] = useState({ x: 0, y: 0 });

  // Resize State
  const [isResizing, setIsResizing] = useState(false);
  const [resizeHandle, setResizeHandle] = useState<string | null>(null);
  const [initialSize, setInitialSize] = useState({ w: 0, h: 0, x: 0, y: 0 });

  // --- Dragging Logic ---
  const handlePointerDown = (e: React.PointerEvent) => {
    e.stopPropagation();
    if (e.button !== 0) return;

    onSelect(element.id);
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialOffset({ x: element.x, y: element.y });

    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDragging) {
      const dx = (e.clientX - dragStart.x) / zoom;
      const dy = (e.clientY - dragStart.y) / zoom;

      let newX = initialOffset.x;
      let newY = initialOffset.y;

      if (element.anchorX === 'left') newX += dx;
      else if (element.anchorX === 'right') newX -= dx;
      else if (element.anchorX === 'center') newX += dx; 

      if (element.anchorY === 'top') newY += dy;
      else if (element.anchorY === 'bottom') newY -= dy;
      else if (element.anchorY === 'center') newY += dy;

      onUpdate(element.id, {
        x: Math.round(newX),
        y: Math.round(newY)
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDragging) {
      setIsDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    }
  };

  // --- Resizing Logic ---
  const handleResizeStart = (e: React.PointerEvent, handle: string) => {
    e.stopPropagation();
    e.preventDefault();
    setIsResizing(true);
    setResizeHandle(handle);
    setDragStart({ x: e.clientX, y: e.clientY });
    setInitialSize({ w: element.width, h: element.height, x: element.x, y: element.y });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handleResizeMove = (e: React.PointerEvent) => {
    if (!isResizing) return;
    e.stopPropagation();

    const dx = (e.clientX - dragStart.x) / zoom;
    const dy = (e.clientY - dragStart.y) / zoom;

    let newWidth = initialSize.w;
    let newHeight = initialSize.h;
    let newX = initialSize.x;
    let newY = initialSize.y;

    if (resizeHandle?.includes('e')) {
        newWidth = Math.max(20, initialSize.w + dx);
    }
    if (resizeHandle?.includes('s')) {
        newHeight = Math.max(20, initialSize.h + dy);
    }
    if (resizeHandle?.includes('w')) {
        const change = -dx;
        newWidth = Math.max(20, initialSize.w + change);
        if (element.anchorX === 'left') {
             newX = initialSize.x - change;
        } else {
             newX = initialSize.x - (change / 2);
        }
    }
    if (resizeHandle?.includes('n')) {
        const change = -dy;
        newHeight = Math.max(20, initialSize.h + change);
        if (element.anchorY === 'top') {
             newY = initialSize.y - change;
        } else if (element.anchorY === 'center') {
             newY = initialSize.y - (change / 2);
        }
    }

    onUpdate(element.id, {
        width: Math.round(newWidth),
        height: Math.round(newHeight),
        x: Math.round(newX),
        y: Math.round(newY)
    });
  };

  const handleResizeUp = (e: React.PointerEvent) => {
    if (isResizing) {
        setIsResizing(false);
        setResizeHandle(null);
        (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    }
  };

  // --- Style Construction ---
  const style: React.CSSProperties = {
    position: 'absolute',
    width: `${element.width}px`,
    height: `${element.height}px`,
    left: element.anchorX === 'left' ? `${element.x}px` : element.anchorX === 'center' ? '50%' : undefined,
    right: element.anchorX === 'right' ? `${element.x}px` : undefined,
    top: element.anchorY === 'top' ? `${element.y}px` : element.anchorY === 'center' ? '50%' : undefined,
    bottom: element.anchorY === 'bottom' ? `${element.y}px` : undefined,
    transform: `
      ${element.anchorX === 'center' ? 'translateX(-50%)' : ''} 
      ${element.anchorY === 'center' ? 'translateY(-50%)' : ''}
    `.trim(),
    marginLeft: element.anchorX === 'center' ? `${element.x}px` : undefined,
    marginTop: element.anchorY === 'center' ? `${element.y}px` : undefined,

    backgroundColor: element.style.backgroundColor,
    color: element.style.color,
    fontSize: `${element.style.fontSize}px`,
    fontWeight: element.style.fontWeight,
    borderRadius: `${element.style.borderRadius}px`,
    borderWidth: `${element.style.borderWidth}px`,
    borderColor: element.style.borderColor,
    borderStyle: element.style.borderWidth ? 'solid' : 'none',
    textAlign: element.style.textAlign,
    opacity: element.style.opacity,
    zIndex: element.style.zIndex,
    boxShadow: element.style.boxShadow,
    display: 'flex',
    alignItems: element.type === 'text' ? 'flex-start' : 'center',
    justifyContent: element.type === 'text' 
      ? (element.style.textAlign === 'center' ? 'center' : element.style.textAlign === 'right' ? 'flex-end' : 'flex-start') 
      : 'center',
    cursor: isDragging ? 'grabbing' : 'grab',
    userSelect: 'none',
  };

  const handleStyle = (pos: string) => {
      const s: React.CSSProperties = { position: 'absolute', width: 10, height: 10, background: 'white', border: '1px solid #6366f1', borderRadius: '50%', zIndex: 50 };
      if (pos === 'nw') { s.left = -5; s.top = -5; s.cursor = 'nw-resize'; }
      if (pos === 'ne') { s.right = -5; s.top = -5; s.cursor = 'ne-resize'; }
      if (pos === 'sw') { s.left = -5; s.bottom = -5; s.cursor = 'sw-resize'; }
      if (pos === 'se') { s.right = -5; s.bottom = -5; s.cursor = 'se-resize'; }
      return s;
  };

  return (
    <>
      <div
        ref={elementRef}
        style={style}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        className={`group ${isSelected ? 'ring-2 ring-indigo-500' : 'hover:ring-1 hover:ring-indigo-300'}`}
        onDoubleClick={(e) => {
             e.stopPropagation();
             if(element.type === 'text') {
                 const newContent = prompt("テキストを編集", element.content);
                 if(newContent !== null) onUpdate(element.id, { content: newContent });
             }
        }}
      >
        {element.type === 'image' && (
          <img src={element.src} alt="" className="w-full h-full object-cover pointer-events-none" style={{ borderRadius: 'inherit' }} />
        )}

        {element.type === 'text' && (
          <div className="w-full h-full p-2 break-words whitespace-pre-wrap pointer-events-none">
            {element.content}
          </div>
        )}

        {(element.type === 'rectangle' || element.type === 'circle' || element.type === 'button') && (
           <div className="w-full h-full p-2 break-words whitespace-pre-wrap pointer-events-none flex items-center justify-center">
             {element.content}
           </div>
        )}

        {element.type === 'menubar' && (
             <div className="w-full h-full flex items-center px-6 pointer-events-none" style={{
                 justifyContent: element.style.textAlign === 'right' ? 'flex-end' : element.style.textAlign === 'center' ? 'center' : 'flex-start',
                 gap: '24px'
             }}>
                 {element.menuItems?.map(item => (
                     <span key={item.id} className="font-medium hover:opacity-70 transition-opacity">{item.label}</span>
                 ))}
             </div>
        )}

        {isSelected && (
            <>
                <div style={handleStyle('nw')} onPointerDown={(e) => handleResizeStart(e, 'nw')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('ne')} onPointerDown={(e) => handleResizeStart(e, 'ne')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('sw')} onPointerDown={(e) => handleResizeStart(e, 'sw')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
                <div style={handleStyle('se')} onPointerDown={(e) => handleResizeStart(e, 'se')} onPointerMove={handleResizeMove} onPointerUp={handleResizeUp}/>
            </>
        )}
      </div>
    </>
  );
};

export default CanvasElement;

import React from 'react';
import { EditorElement, AnchorX, AnchorY, PRESET_COLORS, MenuItem } from '../types';
import { Trash2, AlignLeft, AlignCenter, AlignRight, Copy, ArrowRight, ArrowDown, Plus } from 'lucide-react';

interface PropertiesPanelProps {
  element: EditorElement | null;
  onUpdate: (id: string, updates: Partial<EditorElement>) => void;
  onDelete: (id: string) => void;
  onDuplicate: (element: EditorElement) => void;
  canvasWidth: number;
  canvasHeight: number;
}

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ element, onUpdate, onDelete, onDuplicate, canvasWidth, canvasHeight }) => {
  if (!element) {
    return (
      <div className="w-80 bg-white border-l border-gray-200 p-6 flex flex-col items-center justify-center text-gray-400 z-10 shrink-0">
        <p className="text-sm text-center">要素を選択して<br/>編集してください</p>
      </div>
    );
  }

  const updateStyle = (key: keyof typeof element.style, value: any) => {
    onUpdate(element.id, {
      style: { ...element.style, [key]: value }
    });
  };

  const changeAnchor = (newXAnchor: AnchorX, newYAnchor: AnchorY) => {
    let currentAbsLeft = 0;
    let currentAbsTop = 0;

    if (element.anchorX === 'left') currentAbsLeft = element.x;
    else if (element.anchorX === 'right') currentAbsLeft = canvasWidth - element.width - element.x;
    else if (element.anchorX === 'center') currentAbsLeft = (canvasWidth / 2) + element.x - (element.width / 2);

    if (element.anchorY === 'top') currentAbsTop = element.y;
    else if (element.anchorY === 'bottom') currentAbsTop = canvasHeight - element.height - element.y;
    else if (element.anchorY === 'center') currentAbsTop = (canvasHeight / 2) + element.y - (element.height / 2);

    let newX = 0;
    let newY = 0;

    if (newXAnchor === 'left') newX = currentAbsLeft;
    else if (newXAnchor === 'right') newX = canvasWidth - element.width - currentAbsLeft;
    else if (newXAnchor === 'center') newX = currentAbsLeft - (canvasWidth / 2) + (element.width / 2);

    if (newYAnchor === 'top') newY = currentAbsTop;
    else if (newYAnchor === 'bottom') newY = canvasHeight - element.height - currentAbsTop;
    else if (newYAnchor === 'center') newY = currentAbsTop - (canvasHeight / 2) + (element.height / 2);

    onUpdate(element.id, {
        anchorX: newXAnchor,
        anchorY: newYAnchor,
        x: Math.round(newX),
        y: Math.round(newY)
    });
  };

  const updateMenuItem = (index: number, field: keyof MenuItem, value: string) => {
      if (!element.menuItems) return;
      const newItems = [...element.menuItems];
      newItems[index] = { ...newItems[index], [field]: value };
      onUpdate(element.id, { menuItems: newItems });
  };

  const addMenuItem = () => {
      const newItems = [...(element.menuItems || []), { id: Date.now().toString(), label: '新規リンク', link: '#' }];
      onUpdate(element.id, { menuItems: newItems });
  };

  const removeMenuItem = (index: number) => {
      if (!element.menuItems) return;
      const newItems = element.menuItems.filter((_, i) => i !== index);
      onUpdate(element.id, { menuItems: newItems });
  };

  const AnchorGrid = () => (
      <div className="grid grid-cols-3 gap-1 w-20 h-20 bg-gray-100 p-1 rounded">
          {['top', 'center', 'bottom'].map(y => (
              ['left', 'center', 'right'].map(x => {
                  const isActive = element.anchorX === x && element.anchorY === y;
                  return (
                      <button 
                        key={`${x}-${y}`}
                        onClick={() => changeAnchor(x as AnchorX, y as AnchorY)}
                        className={`rounded-sm border ${isActive ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-gray-300 hover:border-gray-400'}`}
                        title={`${y} - ${x}`}
                      />
                  )
              })
          ))}
      </div>
  );

  return (
    <div className="w-80 bg-white border-l border-gray-200 flex flex-col z-10 shrink-0 h-full overflow-y-auto">
      <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
        <span className="font-semibold text-gray-700 text-sm">プロパティ</span>
        <div className="flex gap-2">
           <button 
            onClick={() => onDuplicate(element)}
            className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded transition"
            title="複製"
          >
            <Copy size={16} />
          </button>
          <button 
            onClick={() => onDelete(element.id)}
            className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded transition"
            title="削除"
          >
            <Trash2 size={16} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-6">

        {/* Content Section */}
        {element.type === 'text' || element.type === 'button' ? (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">テキスト内容</label>
            <textarea
              className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
              rows={3}
              value={element.content}
              onChange={(e) => onUpdate(element.id, { content: e.target.value })}
            />
          </div>
        ) : null}

        {element.type === 'image' && (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">画像 URL</label>
            <input
              type="text"
              className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={element.src || ''}
              onChange={(e) => onUpdate(element.id, { src: e.target.value })}
            />
          </div>
        )}

        {element.type === 'menubar' && (
            <div className="space-y-3">
                 <label className="text-xs font-semibold text-gray-500 uppercase">メニュー項目</label>
                 <div className="space-y-2">
                     {element.menuItems?.map((item, idx) => (
                         <div key={item.id} className="flex flex-col gap-1 p-2 border border-gray-200 rounded bg-gray-50">
                             <div className="flex gap-1">
                                 <input 
                                    className="flex-1 p-1 border rounded text-xs" 
                                    placeholder="ラベル"
                                    value={item.label}
                                    onChange={(e) => updateMenuItem(idx, 'label', e.target.value)}
                                 />
                                 <button onClick={() => removeMenuItem(idx)} className="text-gray-400 hover:text-red-500"><Trash2 size={14}/></button>
                             </div>
                             <input 
                                className="w-full p-1 border rounded text-xs text-gray-600" 
                                placeholder="リンク URL (例: #about)"
                                value={item.link}
                                onChange={(e) => updateMenuItem(idx, 'link', e.target.value)}
                             />
                         </div>
                     ))}
                     <button 
                        onClick={addMenuItem}
                        className="w-full py-1 text-xs border border-dashed border-gray-300 rounded text-gray-500 hover:bg-gray-50 flex items-center justify-center gap-1"
                     >
                        <Plus size={12}/> 項目を追加
                     </button>
                 </div>
            </div>
        )}

        {/* CSS Positioning & Anchor */}
        <div className="space-y-3">
          <label className="text-xs font-semibold text-gray-500 uppercase flex items-center justify-between">
              <span>配置・サイズ (CSS)</span>
          </label>

          <div className="flex gap-4">
              <div className="flex flex-col gap-1 items-center">
                   <span className="text-[10px] text-gray-400">基準位置</span>
                   <AnchorGrid />
              </div>
              <div className="flex-1 space-y-2">
                 <div className="grid grid-cols-2 gap-2">
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                            {element.anchorX === 'left' ? <ArrowRight size={10}/> : element.anchorX === 'right' ? <ArrowRight size={10} className="rotate-180"/> : <ArrowRight size={10} className="text-transparent"/>}
                            {element.anchorX === 'left' ? '左から' : element.anchorX === 'right' ? '右から' : '中央X'}
                        </label>
                        <input type="number" value={element.x} onChange={(e) => onUpdate(element.id, { x: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                             {element.anchorY === 'top' ? <ArrowDown size={10}/> : element.anchorY === 'bottom' ? <ArrowDown size={10} className="rotate-180"/> : <ArrowDown size={10} className="text-transparent"/>}
                            {element.anchorY === 'top' ? '上から' : element.anchorY === 'bottom' ? '下から' : '中央Y'}
                        </label>
                        <input type="number" value={element.y} onChange={(e) => onUpdate(element.id, { y: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">幅 (px)</label>
                        <input type="number" value={element.width} onChange={(e) => onUpdate(element.id, { width: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">高さ (px)</label>
                        <input type="number" value={element.height} onChange={(e) => onUpdate(element.id, { height: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                 </div>
              </div>
          </div>
        </div>

        {/* Typography */}
        {(element.type === 'text' || element.type === 'button' || element.type === 'menubar') && (
           <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">タイポグラフィ</label>
            <div className="flex gap-2">
                 <input 
                    type="number" 
                    value={element.style.fontSize || 16} 
                    onChange={(e) => updateStyle('fontSize', Number(e.target.value))}
                    className="w-20 p-2 border rounded text-sm"
                    title="フォントサイズ"
                 />
                 <div className="flex border rounded overflow-hidden">
                    <button onClick={() => updateStyle('textAlign', 'left')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'left' ? 'bg-gray-100' : ''}`}><AlignLeft size={16}/></button>
                    <button onClick={() => updateStyle('textAlign', 'center')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'center' ? 'bg-gray-100' : ''}`}><AlignCenter size={16}/></button>
                    <button onClick={() => updateStyle('textAlign', 'right')} className={`p-2 hover:bg-gray-100 ${element.style.textAlign === 'right' ? 'bg-gray-100' : ''}`}><AlignRight size={16}/></button>
                 </div>
            </div>
            <div className="flex gap-2 items-center">
                <input 
                    type="color" 
                    value={element.style.color || '#000000'}
                    onChange={(e) => updateStyle('color', e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-none"
                />
                <span className="text-xs text-gray-600">文字色</span>
            </div>
           </div>
        )}

        {/* Appearance */}
        <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">見た目</label>

            <div className="space-y-1">
                <div className="flex justify-between items-center">
                    <span className="text-xs text-gray-600">背景色</span>
                    <input 
                        type="color" 
                        value={element.style.backgroundColor || '#ffffff'}
                        onChange={(e) => updateStyle('backgroundColor', e.target.value)}
                        className="w-6 h-6 rounded cursor-pointer border-none"
                    />
                </div>
                <div className="flex flex-wrap gap-1 mt-1">
                    {PRESET_COLORS.map(c => (
                        <button 
                            key={c}
                            className="w-5 h-5 rounded-full border border-gray-200"
                            style={{ backgroundColor: c }}
                            onClick={() => updateStyle('backgroundColor', c)}
                        />
                    ))}
                    <button 
                        className="w-5 h-5 rounded-full border border-gray-200 bg-transparent text-[8px] flex items-center justify-center text-red-500"
                        onClick={() => updateStyle('backgroundColor', 'transparent')}
                        title="透明"
                    >x</button>
                </div>
            </div>

            <div className="mt-4">
                <span className="text-xs text-gray-600 block mb-1">角丸 ({element.style.borderRadius || 0}px)</span>
                <input 
                    type="range" 
                    min="0" 
                    max="100" 
                    value={element.style.borderRadius || 0} 
                    onChange={(e) => updateStyle('borderRadius', Number(e.target.value))}
                    className="w-full accent-indigo-600"
                />
            </div>

             <div className="mt-4">
                <span className="text-xs text-gray-600 block mb-1">不透明度 ({Math.round((element.style.opacity || 1) * 100)}%)</span>
                <input 
                    type="range" 
                    min="0" 
                    max="1" 
                    step="0.01"
                    value={element.style.opacity ?? 1} 
                    onChange={(e) => updateStyle('opacity', Number(e.target.value))}
                    className="w-full accent-indigo-600"
                />
            </div>

            <div className="mt-4 flex items-center gap-2">
                 <input 
                    type="checkbox"
                    checked={!!element.style.boxShadow}
                    onChange={(e) => updateStyle('boxShadow', e.target.checked ? '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)' : undefined)}
                    className="accent-indigo-600"
                 />
                 <span className="text-xs text-gray-600">影をつける</span>
            </div>
        </div>

        <div className="pt-4 border-t border-gray-100">
             <div className="space-y-2">
                <label className="text-xs font-semibold text-gray-500 uppercase">レイヤー</label>
                <div className="flex gap-2">
                    <button onClick={() => updateStyle('zIndex', (element.style.zIndex || 1) + 1)} className="flex-1 bg-gray-100 hover:bg-gray-200 text-xs py-1 px-2 rounded">前面へ</button>
                    <button onClick={() => updateStyle('zIndex', Math.max(0, (element.style.zIndex || 1) - 1))} className="flex-1 bg-gray-100 hover:bg-gray-200 text-xs py-1 px-2 rounded">背面へ</button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

