    const newElements = elements.filter(el => el.id !== id);
    updateElements(newElements);
    setSelectedId(null);
  };

  const handleDuplicateElement = (element: EditorElement) => {
    const newElement = {
        ...element,
        id: Date.now().toString(),
        x: element.x + 20,
        y: element.y + 20,
        menuItems: element.menuItems ? [...element.menuItems] : undefined
    };
    const newElements = [...elements, newElement];
    updateElements(newElements);
    setSelectedId(newElement.id);
  };

  const handleExport = async () => {
    await downloadBundle(elements);
  };

  // --- Zoom & Pan Logic ---
  useEffect(() => {
    const wrapper = canvasWrapperRef.current;
    if (!wrapper) return;

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();

      // Ctrl + Wheel OR Pinch Gesture -> ZOOM
      if (e.ctrlKey) {
        const rect = wrapper.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        // Calculate where the mouse is relative to the canvas content (World Coordinates)
        // formula: screen = world * zoom + pan
        // therefore: world = (screen - pan) / zoom
        const worldX = (mouseX - pan.x) / zoom;
        const worldY = (mouseY - pan.y) / zoom;

        // Calculate New Zoom
        const zoomDelta = -e.deltaY * 0.002; // sensitivity
        const newZoom = Math.min(5, Math.max(0.1, zoom + zoomDelta));

        // Calculate New Pan to keep the world point under the mouse
        // newPan = mouse - world * newZoom
        const newPanX = mouseX - worldX * newZoom;
        const newPanY = mouseY - worldY * newZoom;

        setZoom(newZoom);
        setPan({ x: newPanX, y: newPanY });
      } else {
        // Normal Wheel -> PAN
        setPan(prev => ({
            x: prev.x - e.deltaX,
            y: prev.y - e.deltaY
        }));
      }
    };

    wrapper.addEventListener('wheel', handleWheel, { passive: false });
    return () => {
      wrapper.removeEventListener('wheel', handleWheel);
    };
  }, [zoom, pan]);

  // Handle Space+Drag or Middle Click Drag for Panning
  const handleWrapperPointerDown = (e: React.PointerEvent) => {
      // If middle click or holding Space (not implemented here but common)
      // For now, let's allow dragging the background if not clicking an element
      if (e.button === 0 || e.button === 1) {
          setIsPanning(true);
          (e.currentTarget as HTMLDivElement).setPointerCapture(e.pointerId);
      }
  };

  const handleWrapperPointerMove = (e: React.PointerEvent) => {
      if (isPanning) {
          setPan(prev => ({
              x: prev.x + e.movementX,
              y: prev.y + e.movementY
          }));
      }
  };

  const handleWrapperPointerUp = (e: React.PointerEvent) => {
      setIsPanning(false);
      (e.currentTarget as HTMLDivElement).releasePointerCapture(e.pointerId);
  };

  // Manual Zoom Buttons (Center Zoom)
  const handleManualZoom = (delta: number) => {
      if (!canvasWrapperRef.current) return;
      const { clientWidth, clientHeight } = canvasWrapperRef.current;

      const newZoom = Math.min(5, Math.max(0.1, zoom + delta));

      // Zoom towards center of viewport
      const centerX = clientWidth / 2;
      const centerY = clientHeight / 2;

      const worldX = (centerX - pan.x) / zoom;
      const worldY = (centerY - pan.y) / zoom;

      const newPanX = centerX - worldX * newZoom;
      const newPanY = centerY - worldY * newZoom;

      setZoom(newZoom);
      setPan({ x: newPanX, y: newPanY });
  };


  const selectedElement = elements.find(el => el.id === selectedId) || null;

  return (
    <div className="flex h-screen flex-col overflow-hidden text-slate-800">
      <header className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0 z-20">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">
            FB
          </div>
          <h1 className="font-bold text-lg tracking-tight">FriendBuilder</h1>
        </div>

        <div className="flex items-center gap-4">
            <div className="flex bg-gray-100 rounded-md p-1 gap-1">
                <button onClick={handleUndo} disabled={historyIndex === 0} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Undo size={16}/></button>
                <button onClick={handleRedo} disabled={historyIndex === history.length -1} className="p-1.5 hover:bg-white rounded disabled:opacity-30 transition"><Redo size={16}/></button>
            </div>
            <div className="h-6 w-px bg-gray-300 mx-2"></div>
            <button 
                onClick={handleExport}
                className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-700 transition shadow-sm"
            >
                <Download size={16} />
                <span>書き出し (Zip)</span>
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <Toolbar onAdd={handleAddElement} />

        {/* Canvas Area */}
        <div 
            ref={canvasWrapperRef}
            className="flex-1 bg-gray-200 overflow-hidden relative"
            onPointerDown={handleWrapperPointerDown}
            onPointerMove={handleWrapperPointerMove}
            onPointerUp={handleWrapperPointerUp}
            onPointerLeave={handleWrapperPointerUp}
            style={{ cursor: isPanning ? 'grabbing' : 'default' }}
            onClick={(e) => {
                if (!isPanning) setSelectedId(null);
            }}
        >
            <div className="absolute bottom-6 left-6 flex bg-white shadow-lg rounded-full p-1 gap-2 z-20">
                <button onClick={() => handleManualZoom(-0.1)} className="p-2 hover:bg-gray-100 rounded-full"><ZoomOut size={16}/></button>
                <span className="text-xs flex items-center font-medium w-8 justify-center">{Math.round(zoom * 100)}%</span>
                <button onClick={() => handleManualZoom(0.1)} className="p-2 hover:bg-gray-100 rounded-full"><ZoomIn size={16}/></button>
            </div>

            <div 
                className="bg-white shadow-xl absolute transition-none" // Disable transition for smooth dragging
                style={{ 
                    width: `${CANVAS_WIDTH}px`, 
                    height: `${CANVAS_HEIGHT}px`,
                    transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
                    transformOrigin: '0 0', // Crucial for matrix-like zoom math
                    backgroundImage: 'radial-gradient(#e5e7eb 1px, transparent 1px)',
                    backgroundSize: '20px 20px'
                }}
                onPointerDown={(e) => e.stopPropagation()} // Prevent wrapper pan when clicking canvas
            >
                {elements.map(el => (
                    <CanvasElement 
                        key={el.id}
                        element={el}
                        isSelected={el.id === selectedId}
                        onSelect={setSelectedId}
                        onUpdate={handleUpdateElement}
                        zoom={zoom}
                    />
                ))}
            </div>
        </div>

        <PropertiesPanel 
            element={selectedElement} 
            onUpdate={handleUpdateElement}
            onDelete={handleDeleteElement}
            onDuplicate={handleDuplicateElement}
            canvasWidth={CANVAS_WIDTH}
            canvasHeight={CANVAS_HEIGHT}
        />
      </div>
    </div>
  );
};

export default App;

export type ElementType = 'text' | 'rectangle' | 'circle' | 'image' | 'button' | 'menubar' | 'svg' | 'hamburger';

export type AnchorX = 'left' | 'center' | 'right';
export type AnchorY = 'top' | 'center' | 'bottom';

export interface MenuItem {
  id: string;
  label: string;
  link: string;
  position?: 'left' | 'right'; // Added for split layout
}

export interface EditorElement {
  id: string;
  type: ElementType;
  // x and y now represent the OFFSET from the anchor point
  x: number; 
  y: number;
  anchorX: AnchorX;
  anchorY: AnchorY;
  width: number;
  height: number;
  content?: string;
  svgContent?: string; // For SVG type
  menuItems?: MenuItem[]; // For menubar and hamburger
  style: {
    backgroundColor?: string;
    color?: string;
    fontSize?: number;
    fontWeight?: string;
    borderRadius?: number;
    borderWidth?: number;
    borderColor?: string;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    zIndex?: number;
    boxShadow?: string;
    gap?: number; // For flex gap
    padding?: number; // For container padding
  };
  src?: string; // For images
  imageName?: string; // For export filename
  link?: string; // For link interaction
}

export const PRESET_COLORS = [
  '#ffffff', '#000000', '#ef4444', '#f97316', '#f59e0b', 
  '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#6366f1', 
  '#8b5cf6', '#d946ef', '#f43f5e', '#64748b'
];

import React, { useRef } from 'react';
import { EditorElement, AnchorX, AnchorY, PRESET_COLORS, MenuItem } from '../types';
import { Trash2, AlignLeft, AlignCenter, AlignRight, Copy, ArrowRight, ArrowDown, Plus, Upload, Image as ImageIcon, FileCode } from 'lucide-react';

interface PropertiesPanelProps {
  element: EditorElement | null;
  onUpdate: (id: string, updates: Partial<EditorElement>) => void;
  onDelete: (id: string) => void;
  onDuplicate: (element: EditorElement) => void;
  canvasWidth: number;
  canvasHeight: number;
}

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ element, onUpdate, onDelete, onDuplicate, canvasWidth, canvasHeight }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const svgInputRef = useRef<HTMLInputElement>(null);

  if (!element) {
    return (
      <div className="w-80 bg-white border-l border-gray-200 p-6 flex flex-col items-center justify-center text-gray-400 z-10 shrink-0">
        <p className="text-sm text-center">要素を選択して<br/>編集してください</p>
      </div>
    );
  }

  const updateStyle = (key: keyof typeof element.style, value: any) => {
    onUpdate(element.id, {
      style: { ...element.style, [key]: value }
    });
  };

  const changeAnchor = (newXAnchor: AnchorX, newYAnchor: AnchorY) => {
    let currentAbsLeft = 0;
    let currentAbsTop = 0;

    if (element.anchorX === 'left') currentAbsLeft = element.x;
    else if (element.anchorX === 'right') currentAbsLeft = canvasWidth - element.width - element.x;
    else if (element.anchorX === 'center') currentAbsLeft = (canvasWidth / 2) + element.x - (element.width / 2);

    if (element.anchorY === 'top') currentAbsTop = element.y;
    else if (element.anchorY === 'bottom') currentAbsTop = canvasHeight - element.height - element.y;
    else if (element.anchorY === 'center') currentAbsTop = (canvasHeight / 2) + element.y - (element.height / 2);

    let newX = 0;
    let newY = 0;

    if (newXAnchor === 'left') newX = currentAbsLeft;
    else if (newXAnchor === 'right') newX = canvasWidth - element.width - currentAbsLeft;
    else if (newXAnchor === 'center') newX = currentAbsLeft - (canvasWidth / 2) + (element.width / 2);

    if (newYAnchor === 'top') newY = currentAbsTop;
    else if (newYAnchor === 'bottom') newY = canvasHeight - element.height - currentAbsTop;
    else if (newYAnchor === 'center') newY = currentAbsTop - (canvasHeight / 2) + (element.height / 2);

    onUpdate(element.id, {
        anchorX: newXAnchor,
        anchorY: newYAnchor,
        x: Math.round(newX),
        y: Math.round(newY)
    });
  };

  const updateMenuItem = (id: string, field: keyof MenuItem, value: string) => {
      if (!element.menuItems) return;
      const newItems = element.menuItems.map(item => 
          item.id === id ? { ...item, [field]: value } : item
      );
      onUpdate(element.id, { menuItems: newItems });
  };

  const addMenuItem = (position: 'left' | 'right' = 'left') => {
      const newItems = [...(element.menuItems || []), { 
          id: Date.now().toString(), 
          label: '新規リンク', 
          link: '#',
          position: position
      }];
      onUpdate(element.id, { menuItems: newItems });
  };

  const removeMenuItem = (id: string) => {
      if (!element.menuItems) return;
      const newItems = element.menuItems.filter(item => item.id !== id);
      onUpdate(element.id, { menuItems: newItems });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              if (event.target?.result) {
                  onUpdate(element.id, { 
                      src: event.target.result as string,
                      imageName: file.name
                  });
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleSvgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              if (event.target?.result) {
                  onUpdate(element.id, { 
                      svgContent: event.target.result as string
                  });
              }
          };
          reader.readAsText(file);
      }
  };

  const AnchorGrid = () => (
      <div className="grid grid-cols-3 gap-1 w-20 h-20 bg-gray-100 p-1 rounded">
          {['top', 'center', 'bottom'].map(y => (
              ['left', 'center', 'right'].map(x => {
                  const isActive = element.anchorX === x && element.anchorY === y;
                  return (
                      <button 
                        key={`${x}-${y}`}
                        onClick={() => changeAnchor(x as AnchorX, y as AnchorY)}
                        className={`rounded-sm border ${isActive ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-gray-300 hover:border-gray-400'}`}
                        title={`${y} - ${x}`}
                      />
                  )
              })
          ))}
      </div>
  );

  const renderMenuItemsList = (position: 'left' | 'right') => {
      // Default to left if undefined
      const items = element.menuItems?.filter(i => (i.position || 'left') === position) || [];

      return (
          <div className="space-y-2">
             <div className="flex justify-between items-center mt-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase">{position === 'left' ? '左寄せ項目' : '右寄せ項目'}</label>
             </div>
             {items.map((item) => (
                 <div key={item.id} className="flex flex-col gap-1 p-2 border border-gray-200 rounded bg-gray-50">
                     <div className="flex gap-1">
                         <input 
                            className="flex-1 p-1 border rounded text-xs" 
                            placeholder="ラベル"
                            value={item.label}
                            onChange={(e) => updateMenuItem(item.id, 'label', e.target.value)}
                         />
                         <button onClick={() => removeMenuItem(item.id)} className="text-gray-400 hover:text-red-500"><Trash2 size={14}/></button>
                     </div>
                     <input 
                        className="w-full p-1 border rounded text-xs text-gray-600" 
                        placeholder="リンク URL (例: #about)"
                        value={item.link}
                        onChange={(e) => updateMenuItem(item.id, 'link', e.target.value)}
                     />
                 </div>
             ))}
             <button 
                onClick={() => addMenuItem(position)}
                className="w-full py-1 text-xs border border-dashed border-gray-300 rounded text-gray-500 hover:bg-gray-50 flex items-center justify-center gap-1"
             >
                <Plus size={12}/> {position === 'left' ? '左' : '右'}に追加
             </button>
          </div>
      );
  };

  return (
    <div className="w-80 bg-white border-l border-gray-200 flex flex-col z-10 shrink-0 h-full overflow-y-auto">
      <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
        <span className="font-semibold text-gray-700 text-sm">プロパティ</span>
        <div className="flex gap-2">
           <button 
            onClick={() => onDuplicate(element)}
            className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded transition"
            title="複製"
          >
            <Copy size={16} />
          </button>
          <button 
            onClick={() => onDelete(element.id)}
            className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded transition"
            title="削除"
          >
            <Trash2 size={16} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-6">

        {/* Content Section */}
        {element.type === 'text' || element.type === 'button' ? (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">テキスト内容</label>
            <textarea
              className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
              rows={3}
              value={element.content}
              onChange={(e) => onUpdate(element.id, { content: e.target.value })}
            />
          </div>
        ) : null}

        {element.type === 'svg' && (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">SVG コード</label>
            <div className="flex flex-col gap-2">
                 <button 
                    onClick={() => svgInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-2 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 transition text-sm text-gray-700"
                >
                    <Upload size={16}/>
                    SVGファイルを選択
                </button>
                <input 
                    type="file" 
                    ref={svgInputRef} 
                    className="hidden" 
                    accept=".svg"
                    onChange={handleSvgUpload}
                />
                <textarea
                  className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none font-mono text-xs"
                  rows={6}
                  value={element.svgContent || ''}
                  onChange={(e) => onUpdate(element.id, { svgContent: e.target.value })}
                  placeholder="<svg>...</svg>"
                />
            </div>
          </div>
        )}

        {element.type === 'image' && (
          <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">画像</label>
            <div className="flex flex-col gap-2">
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center justify-center gap-2 w-full py-2 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 transition text-sm text-gray-700"
                >
                    <Upload size={16}/>
                    PCからアップロード
                </button>
                <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileUpload}
                />

                <div className="relative">
                    <span className="text-[10px] text-gray-400 absolute -top-2 left-2 bg-white px-1">またはURL</span>
                    <input
                        type="text"
                        className="w-full p-2 border border-gray-300 rounded text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                        value={element.src || ''}
                        onChange={(e) => onUpdate(element.id, { src: e.target.value })}
                        placeholder="https://..."
                    />
                </div>
            </div>
            {element.imageName && <p className="text-xs text-gray-500 truncate">File: {element.imageName}</p>}
          </div>
        )}

        {(element.type === 'menubar' || element.type === 'hamburger') && (
            <div className="space-y-3">
                 <label className="text-xs font-semibold text-gray-500 uppercase">メニュー項目</label>

                 {/* Position Settings for Menu Bar */}
                 {element.type === 'menubar' && (
                     <div className="grid grid-cols-2 gap-2 mb-2 p-2 bg-gray-50 border border-gray-200 rounded">
                         <div>
                             <label className="text-[10px] text-gray-500 block mb-1">間隔 (Gap px)</label>
                             <input 
                                type="number" 
                                value={element.style.gap ?? 24} 
                                onChange={(e) => updateStyle('gap', Number(e.target.value))}
                                className="w-full p-1 border rounded text-xs"
                             />
                         </div>
                         <div>
                             <label className="text-[10px] text-gray-500 block mb-1">左右余白 (Pad px)</label>
                             <input 
                                type="number" 
                                value={element.style.padding ?? 24} 
                                onChange={(e) => updateStyle('padding', Number(e.target.value))}
                                className="w-full p-1 border rounded text-xs"
                             />
                         </div>
                     </div>
                 )}

                 {/* Menu Item Lists (Left & Right for Menubar) */}
                 {element.type === 'menubar' ? (
                     <div className="flex flex-col gap-4">
                         {renderMenuItemsList('left')}
                         {renderMenuItemsList('right')}
                     </div>
                 ) : (
                     <div className="space-y-2">
                         {element.menuItems?.map((item) => (
                             <div key={item.id} className="flex flex-col gap-1 p-2 border border-gray-200 rounded bg-gray-50">
                                 <div className="flex gap-1">
                                     <input 
                                        className="flex-1 p-1 border rounded text-xs" 
                                        placeholder="ラベル"
                                        value={item.label}
                                        onChange={(e) => updateMenuItem(item.id, 'label', e.target.value)}
                                     />
                                     <button onClick={() => removeMenuItem(item.id)} className="text-gray-400 hover:text-red-500"><Trash2 size={14}/></button>
                                 </div>
                                 <input 
                                    className="w-full p-1 border rounded text-xs text-gray-600" 
                                    placeholder="リンク URL (例: #about)"
                                    value={item.link}
                                    onChange={(e) => updateMenuItem(item.id, 'link', e.target.value)}
                                 />
                             </div>
                         ))}
                         <button 
                            onClick={() => addMenuItem()}
                            className="w-full py-1 text-xs border border-dashed border-gray-300 rounded text-gray-500 hover:bg-gray-50 flex items-center justify-center gap-1"
                         >
                            <Plus size={12}/> 項目を追加
                         </button>
                     </div>
                 )}
            </div>
        )}

        {/* CSS Positioning & Anchor */}
        <div className="space-y-3">
          <label className="text-xs font-semibold text-gray-500 uppercase flex items-center justify-between">
              <span>配置・サイズ (CSS)</span>
          </label>

          <div className="flex gap-4">
              <div className="flex flex-col gap-1 items-center">
                   <span className="text-[10px] text-gray-400">基準位置</span>
                   <AnchorGrid />
              </div>
              <div className="flex-1 space-y-2">
                 <div className="grid grid-cols-2 gap-2">
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                            {element.anchorX === 'left' ? <ArrowRight size={10}/> : element.anchorX === 'right' ? <ArrowRight size={10} className="rotate-180"/> : <ArrowRight size={10} className="text-transparent"/>}
                            {element.anchorX === 'left' ? '左から' : element.anchorX === 'right' ? '右から' : '中央X'}
                        </label>
                        <input type="number" value={element.x} onChange={(e) => onUpdate(element.id, { x: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400 flex items-center gap-1">
                             {element.anchorY === 'top' ? <ArrowDown size={10}/> : element.anchorY === 'bottom' ? <ArrowDown size={10} className="rotate-180"/> : <ArrowDown size={10} className="text-transparent"/>}
                            {element.anchorY === 'top' ? '上から' : element.anchorY === 'bottom' ? '下から' : '中央Y'}
                        </label>
                        <input type="number" value={element.y} onChange={(e) => onUpdate(element.id, { y: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">幅 (px)</label>
                        <input type="number" value={element.width} onChange={(e) => onUpdate(element.id, { width: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                    <div>
                        <label className="text-[10px] text-gray-400">高さ (px)</label>
                        <input type="number" value={element.height} onChange={(e) => onUpdate(element.id, { height: Number(e.target.value) })} className="w-full p-1 border rounded text-sm" />
                    </div>
                 </div>
              </div>
          </div>
        </div>

        {/* Typography */}
        {(element.type === 'text' || element.type === 'button' || element.type === 'menubar' || element.type === 'hamburger') && (
           <div className="space-y-2">
            <label className="text-xs font-semibold text-gray-500 uppercase">タイポグラフィ</label>
            <div className="flex gap-2">
                 <input 
                    type="number" 
                    value={element.style.fontSize || 16} 
